  private async executeSql(sql: string): Promise<void> {
    const statement = sql.trim();
    if (!statement) return;
    const response = await fetch(`${this.restBaseUrl()}/rpc/ivx_exec_sql`, {
      method: 'POST',
      headers: buildHeaders(),
